import{_ as a,o as r,c as t,ag as o}from"./chunks/framework.B_zcDAFh.js";const g=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),i={name:"guide/faq.md"};function n(s,e,d,l,p,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="the-grass-field-and-explosion-implosion-field-examples-aren-t-working" tabindex="-1">The grass field and explosion/implosion field examples aren&#39;t working. <a class="header-anchor" href="#the-grass-field-and-explosion-implosion-field-examples-aren-t-working" aria-label="Permalink to &quot;The grass field and explosion/implosion field examples aren&#39;t working.&quot;">​</a></h2><p>This is due to a Unity bug in versions where material property blocks passed in for instanced mesh rendering are ignored. The bug was fixed in <strong>Unity 2018.3</strong> — upgrade past that version and the examples will render correctly.</p><h2 id="boing-bones-doesn-t-play-well-with-other-procedural-animation-assets-e-g-final-ik" tabindex="-1">Boing Bones doesn&#39;t play well with other procedural animation assets (e.g. Final IK). <a class="header-anchor" href="#boing-bones-doesn-t-play-well-with-other-procedural-animation-assets-e-g-final-ik" aria-label="Permalink to &quot;Boing Bones doesn&#39;t play well with other procedural animation assets (e.g. Final IK).&quot;">​</a></h2><p>Procedural-animation assets — including Boing Kit — update during <code>LateUpdate</code>, and Unity gives no guaranteed ordering between them. Boing Kit&#39;s update must happen <strong>after</strong> every other procedural-animation script.</p><p>Set this via <strong>Edit &gt; Project Settings &gt; Script Execution Order</strong>. Boing Kit&#39;s post-update pump needs to be last in the list; the pre-update pump needs to be first.</p><h2 id="example-materials-don-t-render-correctly-under-urp-or-hdrp" tabindex="-1">Example materials don&#39;t render correctly under URP or HDRP. <a class="header-anchor" href="#example-materials-don-t-render-correctly-under-urp-or-hdrp" aria-label="Permalink to &quot;Example materials don&#39;t render correctly under URP or HDRP.&quot;">​</a></h2><p>Examples are authored for the <strong>built-in render pipeline</strong> and don&#39;t upgrade cleanly to URP/HDRP. Boing Kit ships stock URP and HDRP shaders and materials (built with shader graphs) that you can swap in — see the <code>Examples/</code> folder for the variants matching your render pipeline.</p><p>For GPU-based reactor field sampling to work, objects need to be rendered with vertex shaders that either use the stock URP/HDRP shader subgraph for per-object or per-vertex effects, or use the helper shader functions Boing Kit provides in <code>BoingKit.cginc</code>:</p><ul><li><code>ApplyBoingReactorFieldPerObject</code></li><li><code>ApplyBoingReactorFieldPerVertex</code></li></ul><p>The <strong>Example Custom Shader</strong> files in the <em>Warped Teapots</em> example show how to call them. For shader graphs, use the shader subgraph shipped under <code>Shader/</code> — see <a href="./boing-reactor-field-sampler.html">Boing Reactor Field Sampler</a>.</p>',11)])])}const u=a(i,[["render",n]]);export{g as __pageData,u as default};
